#include "ember/SfvSelectionAssetPath.hxx"

namespace sfve::assets {

// Generated by CMakeLists.txt from data/pick-space.json (sfve_selection_assets).
extern const char* const kEmbeddedPickSpaceJson;

namespace {

std::wstring Wide(std::string_view text)
{
	return std::wstring(text.begin(), text.end());
}

} // namespace

const picks::PickSpace& EmbeddedPickSpace()
{
	static const picks::PickSpace space = [] {
		picks::PickSpace parsed;
		std::string build, error;
		if (!picks::FromJson(kEmbeddedPickSpaceJson, parsed, build, error)) parsed = {};
		return parsed;
	}();
	return space;
}

// Stream B: the rules. Until then nothing is a selection asset path.
bool IsSfvSelectionAssetPath(const std::wstring&, const picks::PickSpace&)
{
	return false;
}

bool IsSfvSelectionAssetPath(const std::wstring& path)
{
	return IsSfvSelectionAssetPath(path, EmbeddedPickSpace());
}

std::wstring ManifestPath()
{
	return std::wstring(kSelectionRoot) + L"manifest.json";
}

std::wstring CutoutPath(std::string_view fighterCode, int costume, int colour)
{
	if (fighterCode.empty() || costume < 0 || colour < 0) return {};
	return std::wstring(kSelectionRoot) + Wide(fighterCode) + L"\\costume-" + std::to_wstring(costume) + L"\\color-" +
		std::to_wstring(colour) + L"-cutout.png";
}

std::wstring LoadoutPicturePath(std::string_view fighterCode, picks::LoadoutPart part, int choice)
{
	if (fighterCode.empty() || choice < 0 || choice >= picks::kPartChoices) return {};
	return std::wstring(kSelectionRoot) + Wide(fighterCode) + (part == picks::LoadoutPart::VSkill ? L"\\vs" : L"\\vt") +
		std::to_wstring(choice + 1) + L".jpg";
}

} // namespace sfve::assets
